<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {safetyApi,labels,dateLabel,activePenalty,type OwnSafety} from '@/api/moderation'
const data=ref<OwnSafety>({reports:[],penalties:[]}),error=ref(''),busy=ref(false),drafts=ref<Record<string,string>>({});let alive=true
onBeforeUnmount(()=>{alive=false})
async function load(){try{const d=await safetyApi.mine();if(alive)data.value=d}catch(e){if(alive)error.value=(e as Error).message}}
async function appeal(id:string){if(busy.value||!drafts.value[id]?.trim())return;busy.value=true;error.value='';try{await safetyApi.post(`penalties/${id}/appeal`,{reason:drafts.value[id]});if(alive){await load();drafts.value[id]=''}}catch(e){if(alive)error.value=(e as Error).message}finally{if(alive)busy.value=false}}
onMounted(load)
</script>
<template><div class="safety-page"><p class="page-kicker">ACCOUNT SAFETY</p><h2>举报与处罚记录</h2><p class="safety-lead">查看自己提交的举报、账户限制与申诉结果。</p><p v-if="error" role="alert" class="form-error">{{error}}</p><section><header><h3>我的账户限制</h3><button class="table-action" :disabled="busy" @click="load">刷新</button></header><p v-if="!data.penalties.length" class="empty-record">目前没有处罚记录。</p><article v-for="p in data.penalties" :key="p.id" class="safety-record"><div class="record-heading"><b>{{labels[p.kind]}}</b><span>{{p.revoked_at?'已解除':activePenalty(p)?'生效中':'已到期'}}</span></div><p>{{p.reason}}</p><small>开始 {{dateLabel(p.created_at)}} · 截止 {{dateLabel(p.expires_at)}}</small><p v-if="p.appeal">申诉：{{p.appeal}}</p><p v-if="p.appeal_reply">审核回复：{{p.appeal_reply}}</p><p v-else-if="p.appeal" class="empty-record">申诉已提交，等待审核。</p><form v-else-if="activePenalty(p)" @submit.prevent="appeal(p.id)"><label>如果认为处理有误，可以申诉<textarea v-model="drafts[p.id]" required maxlength="1000" rows="3" :disabled="busy" placeholder="说明原因与相关情况。" /></label><button class="button button--ghost button--small" :disabled="busy||!drafts[p.id]?.trim()">提交申诉</button></form></article></section><section v-if="data.decisions?.length"><h3>审核通知</h3><article v-for="d in data.decisions" :key="d.id" class="safety-record"><p>{{d.review_reason}}</p><small>{{dateLabel(d.reviewed_at)}}</small></article></section><section><h3>我提交的举报</h3><p v-if="!data.reports.length" class="empty-record">可在私聊、站内信或群组消息旁提交举报。</p><article v-for="r in data.reports" :key="r.id" class="safety-record"><div class="record-heading"><b>{{r.target_name}}</b><span>{{labels[r.status]}}</span></div><p>{{r.reason}}</p><p v-if="r.review_reason">审核结果：{{r.review_reason}}</p><small>{{dateLabel(r.created_at)}}</small></article></section></div></template>
<style scoped>.safety-page{max-width:960px;margin:0 auto}.safety-lead,.empty-record{color:var(--muted);font-size:13px;line-height:1.8}.safety-page>section{margin-top:36px;border-top:1px solid var(--line);padding-top:24px}.safety-page header,.record-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.safety-record{padding:24px 0;border-bottom:1px solid var(--line);font-size:13px;line-height:1.8;overflow-wrap:anywhere}.safety-record p{white-space:pre-wrap}.safety-record small,.record-heading span{color:var(--muted);font-size:11px}.safety-record form{margin-top:20px;padding:18px;background:var(--code-paper);border-radius:4px}.safety-record label{display:block}.safety-record textarea{display:block;width:100%;font:inherit;padding:12px;margin:10px 0;background:var(--paper);color:var(--ink);border:1px solid var(--line);resize:vertical}</style>
